def solid_lines(grid, color=2):
    """The row indices that are one color throughout and equal to color (solid separator rows)."""
    return [i for i, row in enumerate(grid) if len(row) > 0 and set(row) == {color}]

def drop_marks(grid, color=4, lines=None):
    """Every mark of the given color moves one cell straight down (off-grid marks vanish)."""
    h, w = len(grid), len(grid[0])
    if lines is None: lines = solid_lines(grid)
