    return out

def chevron_from_line(grid, color=4, base=2):
    """A V (chevron) opens upward from just above the nearest mark above the closest solid base line, arms spreading to the grid top; other marks vanish except for their downward shift."""
    h, w = len(grid), len(grid[0])
